using Microsoft.EntityFrameworkCore; using SmartCampusServicePortal.Data;
var b=WebApplication.CreateBuilder(args); b.Services.AddControllersWithViews(); b.Services.AddDbContext<ApplicationDbContext>(o=>o.UseSqlite(b.Configuration.GetConnectionString("DefaultConnection"))); b.Services.AddEndpointsApiExplorer(); b.Services.AddSwaggerGen(); var app=b.Build(); using(var s=app.Services.CreateScope()) s.ServiceProvider.GetRequiredService<ApplicationDbContext>().Database.EnsureCreated(); app.UseStaticFiles(); app.UseRouting(); app.UseSwagger(); app.UseSwaggerUI(); app.MapControllerRoute("default","{controller=Home}/{action=Index}/{id?}"); app.MapControllers(); app.Run();